// producer: HAL-style _links; hrefs resolved against the external request origin
const base = new URL(request.url).origin;      // never leak internal hostnames
const order = { id: 42, customerId: 7, status: 'pending' };
order._links = {
  customer: { href: new URL(`/api/customers/${order.customerId}`, base).href },
  pay:      { href: new URL(`/api/orders/${order.id}/payment`, base).href, method: 'POST' },
};
// consumer: navigate by rel, dereference with fetch
const pay = order._links.pay;                  // find by rel, never by path
if (pay.method !== 'POST') throw new Error('link rel is not a safe transition');
const res = await fetch(pay.href, { method: pay.method });
if (!res.ok) throw new Error(`dangling link: HTTP ${res.status}`);
